const fixture=JSON.parse(await readFile(new URL('./fixtures/short-apply-consent.json',import.meta.url),'utf8')),labels=fixture.messages;assert.equal(Object.keys(labels).length,20);
const diagnostic=process.env.GITHUB_EVENT_NAME==='push';
